package com.yeyamo_mobile.api.notification_service.infrastructure.messaging;
import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.notification_service.application.NotificationIntent;
@Component public class EventNotificationPolicy{private static final Set<String>SUPPORTED=Set.of("user.created","user.role_added","partner.submitted","partner.approved","partner.rejected","partner.needs_info","partner.requires_changes","moderation.report.approved","moderation.report.rejected","messaging.message.sent");private final ObjectMapper mapper;public EventNotificationPolicy(ObjectMapper m){mapper=m;}public List<NotificationIntent> map(JsonNode event){String type=required(event,"eventType");if(!SUPPORTED.contains(type))return List.of();UUID id=UUID.fromString(required(event,"eventId"));if(event.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");JsonNode p=event.path("payload");Map<String,String>vars=new HashMap<>();p.fields().forEachRemaining(e->{if(e.getValue().isValueNode())vars.put(e.getKey(),e.getValue().asText());});vars.putIfAbsent("message",type);String email=text(p,"email");try{String data=mapper.writeValueAsString(p);if(type.equals("messaging.message.sent")){JsonNode recipients=p.path("recipientIds");if(!recipients.isArray())throw new IllegalArgumentException("recipientIds is required");List<NotificationIntent>result=new ArrayList<>();for(JsonNode recipient:recipients)if(!recipient.asText().isBlank())result.add(new NotificationIntent(id,type,recipient.asText(),null,vars,data));return result;}String recipient=switch(type){case"user.created","user.role_added"->required(p,"userId");case"partner.submitted"->required(p,"requesterId");case"partner.approved","partner.rejected","partner.needs_info","partner.requires_changes"->required(p,"ownerUserId");case"moderation.report.approved","moderation.report.rejected"->required(p,"reporterId");default->throw new IllegalArgumentException("Unsupported notification event");};return List.of(new NotificationIntent(id,type,recipient,email,vars,data));}catch(Exception e){throw new IllegalArgumentException("Cannot serialize notification data",e);}}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}}
